const mongoose = require("mongoose");
const { Schema } = mongoose;

const setSchema = new Schema({
  weight: { type: Number, min: 0, max: 1000 },
  reps: { type: String, trim: true, maxlength: 20 },
}, { _id: false });

const lineSchema = new Schema({
  exercise: { type: String, required: true, trim: true }, // Exercise.slug
  name: { type: String, trim: true, maxlength: 100 },
  sets: { type: [setSchema], default: [] },
}, { _id: false });

// A finished workout. clientRef is generated by the browser so a retried upload never duplicates a session.
const workoutSessionSchema = new Schema({
  user: { type: Schema.Types.ObjectId, ref: "User", required: true },
  clientRef: { type: String, required: true, trim: true, maxlength: 64 },
  date: { type: String, match: /^\d{4}-\d{2}-\d{2}$/, required: true },
  day: { type: String, trim: true, maxlength: 20 },
  focus: { type: String, trim: true, maxlength: 80 },
  unit: { type: String, enum: ["kg", "lb"], default: "kg" },
  lines: { type: [lineSchema], default: [] },
}, { timestamps: true });

workoutSessionSchema.index({ user: 1, clientRef: 1 }, { unique: true });
workoutSessionSchema.index({ user: 1, date: -1 });

module.exports = mongoose.model("WorkoutSession", workoutSessionSchema);
